/// <summary>
/// Base class for PricingAttribute table <c>InventModelGroupItem</c>.
/// </summary> 
internal abstract class GUPPricingAttributeInventModelGroupItem extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
protected InventModelGroupItem getTableRecord(Common _pricingObject)
{
    SalesLine            salesLine = _pricingObject as SalesLine;
    InventModelGroupItem inventModelGroupItem;

    if (salesLine.ItemId)
    {
        inventModelGroupItem = InventModelGroupItem::findByItemIdLegalEntity(salesLine.ItemId);
    }

    return inventModelGroupItem;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(InventModelGroupItem));
        qbds.addLink(fieldNum(InventTable, ItemId), fieldNum(InventModelGroupItem, ItemId));
        qbds.addLink(fieldNum(InventTable, dataAreaId), fieldNum(InventModelGroupItem, ItemDataAreaId));
        qbds.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5',
        tableStr(SalesLine),
        tableStr(InventModelGroupItem),
        fieldStr(SalesLine, ItemId),
        fieldStr(InventModelGroupItem, ItemId),
        this.getAttributeFieldIdentifier());
}
